using System;
using System.Collections.Generic;
using Xunit;
using MutationAgentWorkflow.Sample;

public class PasswordValidatorTests
{
    [Fact]
    public void IsValid_NullInput_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.IsValid(null);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_EmptyString_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.IsValid(string.Empty);

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("Ab1!def")] // 7 chars
    [InlineData("Ab1!defg")] // 8 chars
    [InlineData("Ab1!defghijk")] // 12 chars
    [InlineData("Ab1!defghijklmno")] // 16 chars
    [InlineData("Ab1!defghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234!@")] // 64 chars
    public void IsValid_LengthBoundaryInputs_ValidatesLengthRules(string password)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.Equal(password.Length >= PasswordValidator.MinLength && password.Length <= PasswordValidator.MaxLength, result);
    }

    [Fact]
    public void IsValid_LengthGreaterThanMax_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Ab1!defghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ12345!@#"; // 65+ chars

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_MissingUppercase_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "ab1!defg";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_MissingLowercase_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "AB1!DEFG";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_MissingDigit_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Abc!Defg";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_MissingSpecialCharacter_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Abc1Defg";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_CommonPasswordDifferentCasing_ReturnsFalse()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Password";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.False(result);
    }

    [Fact]
    public void IsValid_WhitespaceCharacterIncluded_TreatsWhitespaceAsSpecialCharacter()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Abc1 defg";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.True(result);
    }

    [Fact]
    public void IsValid_ValidPassword_ReturnsTrue()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Abc1!def";

        // Act
        var result = sut.IsValid(password);

        // Assert
        Assert.True(result);
    }

    [Fact]
    public void GetValidationErrors_NullInput_ReturnsSingleEmptyError()
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var errors = sut.GetValidationErrors(null);

        // Assert
        Assert.Single(errors);
    }

    [Fact]
    public void GetValidationErrors_NullInput_ErrorMessageIsPasswordCannotBeEmpty()
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var errors = sut.GetValidationErrors(null);

        // Assert
        Assert.Equal("Password cannot be empty.", errors[0]);
    }

    [Fact]
    public void GetValidationErrors_EmptyString_ReturnsSingleEmptyError()
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var errors = sut.GetValidationErrors(string.Empty);

        // Assert
        Assert.Single(errors);
    }

    [Fact]
    public void GetValidationErrors_ShortPasswordAndMissingCategories_ReturnsMultipleErrors()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "abc";

        // Act
        var errors = sut.GetValidationErrors(password);

        // Assert
        Assert.Equal(4, errors.Count);
    }

    [Fact]
    public void GetValidationErrors_ShortPasswordAndMissingCategories_IncludesLengthError()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "abc";

        // Act
        var errors = sut.GetValidationErrors(password);

        // Assert
        Assert.Contains($"Password must be at least {PasswordValidator.MinLength} characters.", errors);
    }

    [Fact]
    public void GetValidationErrors_TooLongPassword_ReturnsMaxLengthError()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Abc1!defghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ12345!@#";

        // Act
        var errors = sut.GetValidationErrors(password);

        // Assert
        Assert.Contains($"Password must be at most {PasswordValidator.MaxLength} characters.", errors);
    }

    [Fact]
    public void GetValidationErrors_CommonPasswordThatMeetsComplexity_ReturnsCommonPasswordError()
    {
        // Arrange
        var sut = new PasswordValidator();
        var password = "Password1!";

        // Act
        var errors = sut.GetValidationErrors(password);

        // Assert
        Assert.Contains("Password is too common.", errors);
    }

    [Fact]
    public void GetValidationErrors_ValidPassword_ReturnsNoErrors()
    {
        // Arrange
