        var password = "Abc1!def";

        // Act
        var errors = sut.GetValidationErrors(password);

        // Assert
        Assert.Empty(errors);
    }

    [Theory]
    [InlineData("ABC")]
    [InlineData("AbC")]
    [InlineData("Abc123!")]
    public void HasUpperCase_InputsWithUppercaseCharacters_ReturnsTrue(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasUpperCase(input);

        // Assert
        Assert.True(result);
    }

    [Theory]
    [InlineData("abc")]
    [InlineData("123!")]
    [InlineData("")]
    public void HasUpperCase_InputsWithoutUppercaseCharacters_ReturnsFalse(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasUpperCase(input);

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("abc")]
    [InlineData("aBc")]
    [InlineData("A1!b")]
    public void HasLowerCase_InputsWithLowercaseCharacters_ReturnsTrue(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasLowerCase(input);

        // Assert
        Assert.True(result);
    }

    [Theory]
    [InlineData("ABC")]
    [InlineData("123!")]
    [InlineData("")]
    public void HasLowerCase_InputsWithoutLowercaseCharacters_ReturnsFalse(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasLowerCase(input);

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("123")]
    [InlineData("Ab1")]
    [InlineData("!9")]
    public void HasDigit_InputsWithDigitCharacters_ReturnsTrue(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasDigit(input);

        // Assert
        Assert.True(result);
    }

    [Theory]
    [InlineData("abc")]
    [InlineData("ABC!")]
    [InlineData("")]
    public void HasDigit_InputsWithoutDigitCharacters_ReturnsFalse(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasDigit(input);

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("!")]
    [InlineData("Abc1!")]
    [InlineData("abc ")]
    public void HasSpecialCharacter_InputsWithSpecialCharacters_ReturnsTrue(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasSpecialCharacter(input);

        // Assert
        Assert.True(result);
    }

    [Theory]
    [InlineData("abc")]
    [InlineData("ABC123")]
    [InlineData("")]
    public void HasSpecialCharacter_InputsWithoutSpecialCharacters_ReturnsFalse(string input)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.HasSpecialCharacter(input);

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("password", true)]
    [InlineData("Password", true)]
    [InlineData("PASSWORD", true)]
    [InlineData("notcommon", false)]
    public void IsCommonPassword_CommonPasswordChecksAreCaseInsensitive(string password, bool expected)
    {
        // Arrange
        var sut = new PasswordValidator();

        // Act
        var result = sut.IsCommonPassword(password);

        // Assert
        Assert.Equal(expected, result);
    }

    [Fact]
    public void CountUniqueCharacters_RepeatedCharacters_ReturnsOne()
    {
        // Arrange
        var sut = new PasswordValidator();
